#!/usr/bin/env bash
set -Eeuo pipefail
ROOT=/mnt/jfzn/liujn/code/VLAct-PhysToken; cd "$ROOT"
PY=/mnt/jfzn/liujn/miniconda3/envs/vlact/bin/python; ACC=${PY%/python}/accelerate
GPUS=${NODE2_GPUS:-0,1,2,3,4,5,6,7}; PORT=${NODE2_PORT:-30220}; STEPS=${STEPS:-20000}
STATE=$ROOT/artifacts/experiment_runs/node2_ordered/queue.state; LOGDIR=$ROOT/artifacts/experiment_runs/node2_ordered/node2_ordered_ablation_logs; mkdir -p "$LOGDIR"
run_train(){ local id=$1 action=$2 physics=$3; local enabled=true; if [[ $action == false && $physics == false ]]; then enabled=false; fi; local log=$LOGDIR/${id}.log; local out=$ROOT/results/Checkpoints/${id}; local ckpt=$out/checkpoints/steps_${STEPS}_pytorch_model.pt; mkdir -p "$out"; [[ -s $ckpt ]] && return; while :; do set +e; CUDA_VISIBLE_DEVICES=$GPUS WANDB_MODE=disabled $ACC launch --config_file starVLA/config/deepseeds/deepspeed_zero2.yaml --num_processes "${NUM_PROCESSES:-8}" --main_process_port $PORT starVLA/training/train_starvla.py --config_yaml examples/Robotwin/train_files/qwenpi_v4_joint_tokens_d50_smoke.yaml --run_root_dir "$ROOT/results/Checkpoints" --datasets.vla_data.per_device_batch_size 16 --framework.discrete_conditioning.enabled "$enabled" --framework.discrete_conditioning.max_physics_tokens 64 --framework.discrete_conditioning.physics_group_size 2 --framework.discrete_conditioning.physics_vocab_size 128 --framework.discrete_conditioning.physics_condition_enabled $physics --framework.discrete_conditioning.action_condition_enabled $action --framework.joint_token_prediction.physics_token_count 64 --framework.joint_token_prediction.physics_vocab_size 128 --framework.joint_token_prediction.condition_source predicted --datasets.vla_data.discrete_token_cache ./artifacts/token_caches/robotwin_p64_predicted_action4_physics64_full_step20000.npz --trainer.physics_tokenizer_init_checkpoint ./artifacts/physical_language_tokenizers/p64_phi_residual_ema_64x128_full_steps20000/step-00020000.pt --trainer.physics_tokenizer_init_sha256 632c065745d8ee2754b91cbe0ebe494b77ca09fc589bb741a43848f26d396605 --trainer.joint_token_predictor_init_checkpoint null --trainer.policy_extension_init_checkpoint null --trainer.max_train_steps $STEPS --trainer.save_interval 5000 --trainer.eval_interval $((STEPS+1)) --run_id $id >>$log 2>&1; rc=$?; set -e; [[ -s $ckpt ]] && return; echo "retry rc=$rc $(date -Is)" >>$log; sleep 60; done; }
stage(){ local n=$1; shift; grep -qxF "$n" "$STATE" 2>/dev/null && return; "$@"; echo "$n" >>"$STATE"; }
stage clean_no_token run_train qwenpi_v4_clean_no_token_seed42_steps${STEPS} false false
stage physics_only run_train qwenpi_v4_p64_physicsonly_seed42_steps${STEPS} false true
stage action_only run_train qwenpi_v4_p64_actiononly_seed42_steps${STEPS} true false
stage joint run_train qwenpi_v4_p64_m32_predicted_seed42_steps${STEPS} true true
echo "queue complete $(date -Is)"
